diff --git a/repro/issue.js b/repro/issue.js
new file mode 100644
index 0000000..b87bd68
--- /dev/null
+++ b/repro/issue.js
@@ -0,0 +1,17 @@
+/* eslint no-useless-assignment: "error" */
+async function fn() {
+  let intermediaryValue;
+  try {
+    intermediaryValue = 42;
+    unsafeFn();
+    return { error: undefined };
+  } catch {
+    return { intermediaryValue };
+  }
+}
+
+function unsafeFn() {
+  throw new Error();
+}
+
+fn();
diff --git a/repro/no-useless-assignment-try-catch.test.js b/repro/no-useless-assignment-try-catch.test.js
new file mode 100644
index 0000000..2b0c8e5
--- /dev/null
+++ b/repro/no-useless-assignment-try-catch.test.js
@@ -0,0 +1,54 @@
+"use strict";
+
+const rule = require("../lib/rules/no-useless-assignment");
+const RuleTester = require("../lib/rule-tester/rule-tester");
+
+const ruleTester = new RuleTester({ languageOptions: { ecmaVersion: "latest", sourceType: "module" } });
+
+ruleTester.run("no-useless-assignment (try/catch, #19245)", rule, {
+    valid: [
+
+        // Report's snippet: value assigned in try is read in catch, but try ends with `return`.
+        `async function fn() {
+            let intermediaryValue;
+            try {
+                intermediaryValue = 42;
+                unsafeFn();
+                return { error: undefined };
+            } catch {
+                return { intermediaryValue };
+            }
+        }
+        function unsafeFn() { throw new Error(); }
+        fn();`,
+
+        // Same, with `break` ending the try block inside a loop.
+        `function fn() {
+            let v;
+            while (cond()) {
+                try {
+                    v = 42;
+                    unsafeFn();
+                    break;
+                } catch {
+                    console.log(v);
+                }
+            }
+        }
+        fn();`,
+
+        // Control: try block without return/break (currently NOT reported, proving the trigger).
+        `function fn() {
+            let v;
+            try {
+                v = 42;
+                unsafeFn();
+            } catch {
+                return { v };
+            }
+            return {};
+        }
+        fn();`
+    ],
+    invalid: []
+});
